public interface IOrderRepository { Task SaveAsync(Order order); }
public interface IEmailSender { Task SendConfirmationAsync(Order order); }

public class SqlOrderRepository : IOrderRepository
{
    private readonly AppDbContext _db;
    public SqlOrderRepository(AppDbContext db) => _db = db;
    public async Task SaveAsync(Order order) => _db.Orders.Add(order);
}

public class OrderService
{
    private readonly IOrderRepository _repo;
    private readonly IEmailSender _emailSender;

    public OrderService(IOrderRepository repo, IEmailSender emailSender)
    {
        _repo = repo;
        _emailSender = emailSender;
    }

    public async Task PlaceOrder(Order order)
    {
        await _repo.SaveAsync(order);
        await _emailSender.SendConfirmationAsync(order);
    }
}
